select p.id, array(select c from (select substring(p.title from 'zz+') as sub, nullif(p.id, p.id) as nul, (regexp_match(p.title, 'q'))[1] as rm, (array[p.id])[2] as sub2, to_jsonb(p.title) -> 'k' as j, p.id = any(array[null::bigint]) as anynull, case when p.id > 100 then p.id end as cs, p.id / nullif(p.id - p.id, 0) as dv, regexp_substr(p.title, 'q') as rs, array_position(array[p.id], 99) as ap) c) as arr from posts p
